import{_ as s,o as a,c as n,a2 as e}from"./chunks/framework.B4hAkGey.js";const g=JSON.parse('{"title":"12.1 基础入门：中继、分配与租约","description":"","frontmatter":{},"headers":[],"relativePath":"guide/12-handwritten-turn/basics.md","filePath":"guide/12-handwritten-turn/basics.md","lastUpdated":1792683941000}'),r={name:"guide/12-handwritten-turn/basics.md"};function d(o,t,p,l,i,c){return a(),n("div",null,[...t[0]||(t[0]=[e(`<h1 id="_12-1-基础入门-中继、分配与租约" tabindex="-1">12.1 基础入门：中继、分配与租约 <a class="header-anchor" href="#_12-1-基础入门-中继、分配与租约" aria-label="Permalink to &quot;12.1 基础入门：中继、分配与租约&quot;">​</a></h1><blockquote><p>当对称 NAT（Symmetric NAT）让 STUN 反射地址彻底失效时，只剩一条路：让一台有公网 IP 的服务器替你&quot;代收代发&quot;。这就是 <strong>TURN（Traversal Using Relays around NAT，RFC 5766）</strong>。本模块我们将不用任何第三方库，纯手写一个 mini TURN 服务器——先把六个核心方法与一次完整的分配事务讲清楚。</p></blockquote><hr><h2 id="_12-1-1-为什么-stun-会失败-对称-nat" tabindex="-1">12.1.1 为什么 STUN 会失败：对称 NAT <a class="header-anchor" href="#_12-1-1-为什么-stun-会失败-对称-nat" aria-label="Permalink to &quot;12.1.1 为什么 STUN 会失败：对称 NAT&quot;">​</a></h2><p>回忆模块四：STUN 能告诉你&quot;你的公网映射地址（srflx）是什么&quot;。但这个地址有个前提——<strong>NAT 的映射必须对所有目的地保持一致</strong>。</p><p>对称 NAT 恰好打破了这个前提：<strong>每换一个目的地址，NAT 就换一个新的映射端口</strong>。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>  客户端 192.168.1.2:5000</span></span>
<span class="line"><span>    │</span></span>
<span class="line"><span>    ├─ 发包给 STUN 服务器 A  ──► NAT 映射为  114.5.5.5:60001   ← STUN 告诉你这个地址</span></span>
<span class="line"><span>    │</span></span>
<span class="line"><span>    └─ 发包给对端 B         ──► NAT 映射为  114.5.5.5:60002   ← 对端连 60001，根本到不了你！</span></span></code></pre></div><p><strong>5G 网络的残酷现实</strong>：运营商的 CGN（Carrier-Grade NAT，运营商级 NAT）几乎都是对称 NAT。这意味着在 5G 场景下，<strong>TURN 不是可选项，而是兜底刚需</strong>。</p><p>TURN 的思路很直接——既然你们互相够不着，那就都在一台公网服务器上&quot;开个窗口&quot;，所有流量都经过这个窗口中转：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>  客户端 A                                        对端 B</span></span>
<span class="line"><span>     │                                               │</span></span>
<span class="line"><span>     │  ① Allocate：在 TURN 上申请一个中继端口        │</span></span>
<span class="line"><span>     ▼                                               │</span></span>
<span class="line"><span>  ┌────────────────────────┐                         │</span></span>
<span class="line"><span>  │     TURN 服务器         │                         │</span></span>
<span class="line"><span>  │  127.0.0.1:3478 (控制口) │                         │</span></span>
<span class="line"><span>  │  中继口 relayed address  │ ◄──── B 直接发 UDP ─────┘</span></span>
<span class="line"><span>  │  例如 9.9.9.9:52297     │</span></span>
<span class="line"><span>  └────────────────────────┘</span></span>
<span class="line"><span>     ▲</span></span>
<span class="line"><span>     └── B 发给 relayed address 的包，被 TURN 包装后转给 A</span></span></code></pre></div><p>代价也很直接：<strong>所有媒体流量都要经过 TURN 服务器进出两次</strong>，带宽成本高、延迟略增。所以 ICE 永远把 relay 候选排在最后，只在直连和 STUN 都失败时才用。</p><hr><h2 id="_12-1-2-核心概念-分配-allocation" tabindex="-1">12.1.2 核心概念：分配（Allocation） <a class="header-anchor" href="#_12-1-2-核心概念-分配-allocation" aria-label="Permalink to &quot;12.1.2 核心概念：分配（Allocation）&quot;">​</a></h2><p>TURN 的一切从一次 <strong>Allocate（分配）</strong> 开始：</p><table tabindex="0"><thead><tr><th>概念</th><th>含义</th></tr></thead><tbody><tr><td><strong>分配（Allocation）</strong></td><td>客户端在 TURN 服务器上申请到的一个&quot;中继席位&quot;，内含一个 relayed address</td></tr><tr><td><strong>中继地址（relayed address）</strong></td><td>服务器为这个分配专门开的 UDP 端口，对端把数据发到这里</td></tr><tr><td><strong>控制连接</strong></td><td>客户端与 TURN 服务器之间的 STUN/TURN 通道（默认 3478 端口）</td></tr><tr><td><strong>对端（peer）</strong></td><td>真正要和客户端通信的远端</td></tr></tbody></table><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>  客户端 ──── STUN/TURN 消息 ────► TURN 控制口 :3478</span></span>
<span class="line"><span>                                     │</span></span>
<span class="line"><span>                                     │ Allocate 成功后，服务器新开端口</span></span>
<span class="line"><span>                                     ▼</span></span>
<span class="line"><span>  对端   ──── 裸 UDP 数据 ───────► relayed address（如 :52297）</span></span></code></pre></div><blockquote><p><strong>注意</strong>：对端从来不需要懂 TURN 协议。它只要把 UDP 包发到 relayed address，TURN 服务器负责包装转发。</p></blockquote><hr><h2 id="_12-1-3-六个核心方法" tabindex="-1">12.1.3 六个核心方法 <a class="header-anchor" href="#_12-1-3-六个核心方法" aria-label="Permalink to &quot;12.1.3 六个核心方法&quot;">​</a></h2><p>TURN 消息复用 STUN 的报文格式（20 字节头 + TLV 属性），核心方法只有六个：</p><table tabindex="0"><thead><tr><th>方法</th><th>方法号</th><th>类别</th><th>方向</th><th>作用</th></tr></thead><tbody><tr><td><strong>Allocate</strong></td><td>0x003</td><td>request/response</td><td>client → server</td><td>申请分配，拿到 relayed address</td></tr><tr><td><strong>Refresh</strong></td><td>0x004</td><td>request/response</td><td>client → server</td><td>续租；LIFETIME=0 表示主动释放</td></tr><tr><td><strong>CreatePermission</strong></td><td>0x008</td><td>request/response</td><td>client → server</td><td>授权某个 peer IP 可以向我转发数据</td></tr><tr><td><strong>Send indication</strong></td><td>0x006</td><td>indication</td><td>client → server</td><td>&quot;帮我把这段数据发给 peer&quot;</td></tr><tr><td><strong>Data indication</strong></td><td>0x007</td><td>indication</td><td>server → client</td><td>&quot;peer 发来了这段数据&quot;</td></tr><tr><td><strong>ChannelBind</strong></td><td>0x009</td><td>request/response</td><td>client → server</td><td>绑定一个 16-bit 通道号给 peer，之后走轻量 ChannelData</td></tr></tbody></table><blockquote><p>indication（指示）与 request 的区别：<strong>indication 没有响应</strong>，是单向通知。</p></blockquote><p>还有一个特殊的 <strong>ChannelData</strong>：它<strong>不是 STUN 消息</strong>，只是 4 字节头 + 裸数据，靠高两位 <code>01</code> 与 STUN 消息（高两位 <code>00</code>）区分。详见 12.2。</p><hr><h2 id="_12-1-4-一次完整的-allocate-事务" tabindex="-1">12.1.4 一次完整的 Allocate 事务 <a class="header-anchor" href="#_12-1-4-一次完整的-allocate-事务" aria-label="Permalink to &quot;12.1.4 一次完整的 Allocate 事务&quot;">​</a></h2><p>TURN 采用<strong>长期凭证机制（Long-Term Credential）</strong>：第一次请求故意不带凭证，服务器回 <strong>401 Unauthorized</strong> 并给出 REALM（域）和 NONCE（随机数），客户端用这些信息算出摘要后重发。密码本身永远不上网。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>  客户端                                         TURN 服务器</span></span>
<span class="line"><span>    │                                                │</span></span>
<span class="line"><span>    │ ── Allocate request ──────────────────────────►│</span></span>
<span class="line"><span>    │    （无凭证）                                   │</span></span>
<span class="line"><span>    │                                                │</span></span>
<span class="line"><span>    │ ◄── 401 Unauthorized ──────────────────────────│</span></span>
<span class="line"><span>    │     REALM=&quot;mini-turn&quot;, NONCE=&quot;c421d5cf...&quot;     │</span></span>
<span class="line"><span>    │                                                │</span></span>
<span class="line"><span>    │    key = MD5(username:realm:password)          │  ← 客户端本地计算</span></span>
<span class="line"><span>    │                                                │</span></span>
<span class="line"><span>    │ ── Allocate request ──────────────────────────►│</span></span>
<span class="line"><span>    │    USERNAME, REALM, NONCE                      │</span></span>
<span class="line"><span>    │    MESSAGE-INTEGRITY = HMAC-SHA1(key, 报文)     │  ← 服务器校验</span></span>
<span class="line"><span>    │                                                │</span></span>
<span class="line"><span>    │ ◄── Allocate success ──────────────────────────│</span></span>
<span class="line"><span>    │     XOR-RELAYED-ADDRESS = 9.9.9.9:52297  ★     │</span></span>
<span class="line"><span>    │     LIFETIME = 600                             │</span></span>
<span class="line"><span>    │                                                │</span></span></code></pre></div><p>拿到 <strong>XOR-RELAYED-ADDRESS</strong>（异或中继地址）后，客户端就可以把它作为一个 ICE relay 候选交给对端了。地址和端口与魔数（Magic Cookie）<code>0x2112A442</code> 做了异或——防止途中的 NAT 设备&quot;自作聪明&quot;改写载荷里的明文地址。</p><hr><h2 id="_12-1-5-租约与权限的生命周期" tabindex="-1">12.1.5 租约与权限的生命周期 <a class="header-anchor" href="#_12-1-5-租约与权限的生命周期" aria-label="Permalink to &quot;12.1.5 租约与权限的生命周期&quot;">​</a></h2><p>TURN 服务器上的每样东西都会过期——这是为了回收死掉的客户端占用的资源：</p><table tabindex="0"><thead><tr><th>资源</th><th>默认时长</th><th>续期方式</th><th>到期后果</th></tr></thead><tbody><tr><td><strong>分配（Allocation）</strong></td><td><strong>600 秒</strong></td><td>Refresh 请求</td><td>relayed address 回收，全部权限/通道失效</td></tr><tr><td><strong>权限（Permission）</strong></td><td><strong>300 秒（5 分钟）</strong></td><td>重发 CreatePermission</td><td>该 peer IP 的入站数据被丢弃</td></tr><tr><td><strong>通道绑定（Channel Binding）</strong></td><td>600 秒（10 分钟）</td><td>重发 ChannelBind</td><td>回退到 Data indication 方式</td></tr></tbody></table><p>两个容易记混的点：</p><ol><li><strong>Refresh 的 LIFETIME=0</strong> 是&quot;主动释放&quot;，不是&quot;续 0 秒&quot;——服务器立刻回收分配。优雅下线要用它，否则服务器要等 600 秒才能回收资源。</li><li><strong>权限只有 5 分钟</strong>而分配有 10 分钟——通话超过 5 分钟时，千万别忘了重发 CreatePermission，否则会突然收不到对端数据（典型的&quot;通话 5 分多钟必断&quot; bug 的根源）。</li></ol><hr><h2 id="_12-1-6-小结" tabindex="-1">12.1.6 小结 <a class="header-anchor" href="#_12-1-6-小结" aria-label="Permalink to &quot;12.1.6 小结&quot;">​</a></h2><table tabindex="0"><thead><tr><th>你应该记住</th><th></th></tr></thead><tbody><tr><td><strong>对称 NAT 下 STUN 必败</strong></td><td>映射端口随目的地变化，srflx 地址对 peer 无效</td></tr><tr><td><strong>TURN = 公网代收代发</strong></td><td>代价是带宽翻倍、延迟略增</td></tr><tr><td><strong>六个方法</strong></td><td>Allocate / Refresh / CreatePermission / Send ind. / Data ind. / ChannelBind</td></tr><tr><td><strong>401 质询流程</strong></td><td>无凭证 → 401（REALM+NONCE）→ 带 MESSAGE-INTEGRITY 重发 → success</td></tr><tr><td><strong>600s 租约 / 300s 权限</strong></td><td>都要续；LIFETIME=0 主动释放</td></tr></tbody></table><hr><h2 id="下一节" tabindex="-1">下一节 <a class="header-anchor" href="#下一节" aria-label="Permalink to &quot;下一节&quot;">​</a></h2><p>→ <a href="./advanced">12.2 进阶应用：权限、通道与长期凭证</a></p>`,40)])])}const u=s(r,[["render",d]]);export{g as __pageData,u as default};
